import { pgTable, text, timestamp, uuid, varchar } from "drizzle-orm/pg-core";

/**
 * Per-workspace data encryption key (DEK), wrapped with the master key (KEK).
 *
 * `workspace_id` is the primary key and mirrors the Better Auth organization
 * id, which is generated by the auth layer (WP-03), so it carries no default
 * here. It is indexed by virtue of being the primary key.
 */
export const workspaceKey = pgTable("workspace_key", {
  workspaceId: uuid("workspace_id").primaryKey(),
  kekVersion: varchar("kek_version", { length: 64 }).notNull(),
  wrappedDek: text("wrapped_dek").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  rotatedAt: timestamp("rotated_at", { withTimezone: true }),
});
